<!DOCTYPE html>
<html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><link rel="stylesheet" href="../style/style.css"><title>Marketplace : Commandes</title></head>
<body><header class="site-header"><a class="brand" href="../products/catalog_html.php">Marché local</a><nav><a href="../products/catalog_html.php">Catalogue</a><a href="../products/cart_html.php">Panier</a><a href="orders_html.php">Commandes</a><a href="../auth/logout.php">Déconnexion</a></nav></header>
<main><div class="hero-copy"><p class="eyebrow" id="eyebrow">Suivi</p><h1 id="title">Vos commandes.</h1><p id="intro">Retrouvez l'historique et l'état de vos achats.</p></div><div id="orders"></div></main>
<script>
const container = document.getElementById('orders');
const labels = {pending:'En attente', confirmed:'Confirmée', shipped:'Expédiée', delivered:'Livrée', cancelled:'Annulée'};
async function loadOrders() { const response = await fetch('orders_php.php'); const data = await response.json(); if (data.login) { location.href='../auth/login_html.php'; return; } if (!data.orders.length) { container.innerHTML='<div class="empty">Aucune commande pour le moment.</div>'; return; } if (data.role === 'seller') { document.getElementById('eyebrow').textContent='Espace vendeur'; document.getElementById('title').textContent='Les commandes reçues.'; document.getElementById('intro').textContent='Mettez à jour leur statut au fil de leur traitement.'; } container.innerHTML = `<div class="table-wrap"><table><thead><tr><th>Commande</th><th>${data.role === 'seller' ? 'Client' : 'Articles'}</th><th>Total</th><th>Statut</th><th>Date</th>${data.role === 'seller' ? '<th>Action</th>' : ''}</tr></thead><tbody>${data.orders.map(order => `<tr><td>#${order.id}</td><td>${data.role === 'seller' ? `${order.customer_name}<br><span class="muted">${order.customer_email}</span>` : order.items_count + ' article(s)'}</td><td>${Number(order.total_amount).toFixed(2)} €</td><td><span class="status">${labels[order.status] || order.status}</span></td><td>${new Date(order.created_at).toLocaleDateString('fr-FR')}</td>${data.role === 'seller' ? `<td><select class="status-select" data-id="${order.id}">${Object.entries(labels).map(([key, value]) => `<option value="${key}" ${key === order.status ? 'selected' : ''}>${value}</option>`).join('')}</select></td>` : ''}</tr>`).join('')}</tbody></table></div>`; document.querySelectorAll('.status-select').forEach(select => select.addEventListener('change', async () => { await fetch('orders_php.php', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action:'status', order_id:select.dataset.id, status:select.value})}); loadOrders(); })); }
loadOrders();
</script></body></html>
